// Real-time town movement and a playable catch-and-dodge arcade challenge.
const coins=Array.from({length:12},(_,i)=>({id:i,x:65+i*75,y:i%2?310:277}));
const held=new Set();let destination=null,lastFrame=0,run=null,dashUntil=0,particles=[],lastDirection={x:1,y:0};
const baseDraw=draw,baseRender=render,baseShow=show;
function saveGame(){try{localStorage.setItem('core-quest-v2',JSON.stringify(state))}catch{}}
try{const saved=JSON.parse(localStorage.getItem('core-quest-v2'));if(saved&&Array.isArray(saved.completed)&&Array.isArray(saved.collected)&&Array.isArray(saved.badges)&&Number.isFinite(saved.score)){state={...createState(),...saved,completed:saved.completed.filter(id=>missions.some(m=>m.id===id)),collected:saved.collected.filter(id=>Number.isInteger(id)&&id>=0&&id<12),badges:saved.badges.filter(id=>missions.some(m=>m.id===id))};state.player={x:480,y:290};if(state.started){$('#intro').hidden=true;$('#announcement').textContent='Welcome back! Your quest progress was saved on this browser.'}}}catch{}
function nearby(){return missions.map(m=>({m,d:Math.hypot(m.x-state.player.x,m.y+83-state.player.y)})).sort((a,b)=>a.d-b.d)[0]}
function blocked(x,y){return missions.some(m=>x>m.x-83&&x<m.x+83&&y>m.y-90&&y<m.y+71)}
function walk(dx,dy){const x=Math.max(20,Math.min(940,state.player.x+dx)),y=Math.max(32,Math.min(545,state.player.y+dy));if(!blocked(x,state.player.y))state.player.x=x;if(!blocked(state.player.x,y))state.player.y=y;coins.forEach(c=>{if(!state.collected.includes(c.id)&&Math.hypot(c.x-state.player.x,c.y-state.player.y)<24){state.collected.push(c.id);state.score+=10;beep(990);particles.push({x:c.x,y:c.y,t:1,text:'+10 XP'});render();$('#announcement').textContent=state.collected.length===12?'Treasure hunter! All 12 data chips collected. Visit a neighbour for your next quest.':`Data chip found! ${state.collected.length}/12 collected. Each is worth 10 exploration XP.`}})}
draw=function(){baseDraw();const time=performance.now()/250;coins.forEach(c=>{if(!state.collected.includes(c.id)){const y=c.y+Math.sin(time+c.id)*3;rect(c.x-7,y-7,14,14,'#e9cb60');rect(c.x-3,y-3,6,6,'#fff0ac')}});particles.forEach(p=>text(p.text,p.x,p.y-(1-p.t)*30,13,'#f9ea8f'));if(state.started&&!dialog.open){const n=nearby();if(n.d<85){rect(n.m.x-110,n.m.y+111,220,24,'#172c2d');text('[E] '+n.m.name.toUpperCase(),n.m.x,n.m.y+127,11,'#e8f2b0')}}};
render=function(){baseRender();$('#loot').textContent=`◆ ${state.collected.length} / 12`;$('#missions').querySelectorAll('[data-mission]').forEach(b=>{if(state.badges.includes(b.dataset.mission))b.querySelector('span:last-child').textContent='★'});saveGame()};
show=function(html){held.clear();destination=null;baseShow(html)};
interact=function(){if(!state.started){start();return}const n=nearby();if(n.d<100)mission(n.m.id);else $('#announcement').textContent='Find a building’s front door (below its sign), or fast-travel using the quest log.'};
$('#interact').onclick=interact;
dialog.addEventListener('close',()=>{run=null;held.clear();destination=null;canvas.focus();saveGame()});
$('#close-dialog').onclick=()=>dialog.close();
$('#restart').onclick=()=>show(`<p class="eyebrow">NEW ADVENTURE</p><h2 id="dialog-title">Start a fresh quest?</h2><p>This resets your saved quests, collected chips and arcade badges on this browser.</p><button id="confirm-reset" class="primary">YES, START AGAIN</button> <button id="keep-playing">KEEP PLAYING</button>`);
$('#dialog-content').addEventListener('click',e=>{if(e.target.closest('#play-challenge')||e.target.closest('#retry-run'))startRun(activeMission);if(e.target.closest('#run-back'))dialog.close();if(e.target.closest('#run-pause')){if(run){run.paused=!run.paused;$('#run-pause').textContent=run.paused?'▶ RESUME':'Ⅱ PAUSE'}}if(e.target.closest('#confirm-reset')){state=createState();run=null;destination=null;particles=[];dialog.close();$('#intro').hidden=false;render();$('#start').focus();$('#announcement').textContent='Fresh save. Collect chips, meet neighbours and win arcade badges.'}if(e.target.closest('#keep-playing'))dialog.close();});
const keyDir={arrowup:[0,-1],w:[0,-1],arrowdown:[0,1],s:[0,1],arrowleft:[-1,0],a:[-1,0],arrowright:[1,0],d:[1,0]};
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(e.ctrlKey||e.metaKey||e.altKey||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(run&&dialog.open){if(keyDir[key]){e.preventDefault();held.add(key)}if((key==='p'||key===' ')&&!e.repeat&&e.target.tagName!=='BUTTON'){$('#run-pause').click();e.preventDefault()}return}if(dialog.open||!state.started)return;if(keyDir[key]){e.preventDefault();held.add(key);destination=null}if(key==='shift')held.add(key);if((key==='e'||(key==='Enter'.toLowerCase()&&e.target===canvas))&&!e.repeat){e.preventDefault();interact()}});
window.addEventListener('keyup',e=>held.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{held.clear();if(run){run.paused=true;if($('#run-pause'))$('#run-pause').textContent='▶ RESUME'}});document.addEventListener('visibilitychange',()=>{if(document.hidden){held.clear();if(run){run.paused=true;if($('#run-pause'))$('#run-pause').textContent='▶ RESUME'}}});
for(const b of document.querySelectorAll('[data-move]')){const [dx,dy]=b.dataset.move.split(',').map(Number),key=dx<0?'a':dx>0?'d':dy<0?'w':'s';b.onclick=null;b.onpointerdown=e=>{e.preventDefault();if(!state.started)start();destination=null;held.add(key);b.setPointerCapture(e.pointerId)};b.onpointerup=b.onpointercancel=()=>held.delete(key);b.onlostpointercapture=()=>held.delete(key);b.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!e.repeat)move(dx,dy)}}
$('#dash').onclick=()=>{dashUntil=performance.now()+350;walk(lastDirection.x*35,lastDirection.y*35);draw()};
canvas.addEventListener('click',e=>{if(!state.started)return;canvas.focus();const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*960/r.width,y=(e.clientY-r.top)*576/r.height;const m=missions.find(m=>Math.abs(m.x-x)<85&&y>m.y-115&&y<m.y+76);if(m){mission(m.id);return}if(!blocked(x,y))destination={x,y};else $('#announcement').textContent='Walk around the buildings to reach their front doors.'});
const themes={campus:['CAMPUS CATCH','Catch the notes before class!','NOTES'],studio:['RENDER RESCUE','Catch the frames. Keep the cut moving!','FRAME'],cafe:['INBOX SPRINT','Catch the files. Clear the workday!','FILE'],arcade:['PIXEL PATROL','Catch the stars. Dodge the bugs!','STAR'],lab:['DATA DASH','Catch the data. Feed the experiment!','DATA'],park:['COMMON CORE','Catch the chips that connect the town!','CHIP']};
function startRun(id){activeMission=id;const theme=themes[id];show(`<p class="eyebrow">BONUS ARCADE / ${missions.find(m=>m.id===id).name.toUpperCase()}</p><h2 id="dialog-title">${theme[0]}</h2><p class="run-intro">${theme[1]} Collect <b>8 gold packets</b>, avoid <b>pink bugs</b>. You have 3 hearts and 30 seconds.</p><div class="run-hud"><span id="run-count">◆ 0 / 8</span><span id="run-life">♥ ♥ ♥</span><span id="run-time">30s</span><button id="run-pause">Ⅱ PAUSE</button></div><canvas id="run-canvas" width="480" height="300" tabindex="0" aria-label="Catch arcade. Move left and right with arrows or A and D. Or move your mouse or finger over the playfield. Catch gold packets, avoid pink bugs."></canvas><p class="run-help">← → / A D to move · or drag / tap the playfield · P to pause</p><p class="footnote">An arcade challenge for fun, not a processor speed comparison. Same rules for both families. Escape exits safely.</p><button id="run-back">BACK TO TOWN</button>`);run={id,x:240,items:[],caught:0,hearts:3,time:30,spawn:.3,seq:0,paused:false,invulnerable:0,ready:2};held.clear();const c=$('#run-canvas');c.focus();const aim=e=>{if(run&&!run.paused){const r=c.getBoundingClientRect();run.x=Math.max(24,Math.min(456,(e.clientX-r.left)*480/r.width))}};c.onpointermove=e=>{if(e.pointerType==='mouse'||e.buttons)aim(e)};c.onpointerdown=e=>{e.preventDefault();c.setPointerCapture(e.pointerId);aim(e)};}
function finishRun(won){const id=run.id,caught=run.caught;const first=won&&!state.badges.includes(id);if(first){state.badges.push(id);state.score+=150}run=null;held.clear();beep(won?1100:220);render();show(`<p class="eyebrow">${won?'ARCADE CLEARED':'ANOTHER RUN?'}</p><div class="result-badge">${won?'★':'↺'}</div><h2 id="dialog-title">${won?'Packet-perfect!':'The bugs got busy.'}</h2><p>${won?(first?'You earned a town badge and +150 arcade XP!':'Badge already earned. Nice replay!'):`You caught ${caught} of 8 packets. Try again, or keep exploring—your learning progress is safe.`}</p><div class="feedback">${missions.find(m=>m.id===id).why}</div><button class="primary" id="retry-run">▶ ${won?'PLAY AGAIN':'TRY AGAIN'}</button> <button id="run-back">BACK TO TOWN</button>${state.completed.length===6?'<button id="continue">FIND MY PROCESSOR MATCH →</button>':''}`)}
function updateRun(dt){if(!run)return;const c=$('#run-canvas');if(!c){run=null;return}const g=c.getContext('2d');const r=run;if(!r.paused){if(r.ready>0)r.ready=Math.max(0,r.ready-dt);else{r.time-=dt;r.invulnerable=Math.max(0,r.invulnerable-dt);const direction=(held.has('arrowright')||held.has('d')?1:0)-(held.has('arrowleft')||held.has('a')?1:0);r.x=Math.max(24,Math.min(456,r.x+direction*330*dt));r.spawn-=dt;if(r.spawn<=0){r.seq++;const bug=r.seq%3===0;r.items.push({x:35+Math.random()*410,y:-20,bug,speed:bug?120:95});r.spawn=.65}r.items.forEach(item=>{item.y+=item.speed*dt;if(item.y>246&&item.y<282&&Math.abs(item.x-r.x)<31){if(!item.bug){r.caught++;item.y=400;beep(780)}else if(r.invulnerable<=0){r.hearts--;r.invulnerable=1.2;item.y=400;beep(180)}}});r.items=r.items.filter(i=>i.y<330);if(r.caught>=8){finishRun(true);return}if(r.hearts<=0||r.time<=0){finishRun(false);return}}}
g.fillStyle='#162c32';g.fillRect(0,0,480,300);g.strokeStyle='#254049';g.lineWidth=1;for(let i=0;i<480;i+=30){g.beginPath();g.moveTo(i,0);g.lineTo(i,300);g.stroke()}for(let y=0;y<300;y+=30){g.beginPath();g.moveTo(0,y);g.lineTo(480,y);g.stroke()}r.items.forEach(item=>{g.fillStyle=item.bug?'#eb899e':'#edce6b';g.fillRect(item.x-11,item.y-11,22,22);g.fillStyle='#253542';g.font='bold 14px monospace';g.textAlign='center';g.fillText(item.bug?'×':'◆',item.x,item.y+5)});g.fillStyle=r.invulnerable>0&&Math.floor(r.invulnerable*10)%2?'#f5b8a7':'#d8f075';g.fillRect(r.x-22,259,44,15);g.fillRect(r.x-22,248,7,12);g.fillRect(r.x+15,248,7,12);g.fillStyle='#f3f7d8';g.fillRect(r.x-7,277,14,4);g.font='bold 10px monospace';g.textAlign='center';g.fillText('CATCH',r.x,294);if(r.paused||r.ready>0){g.fillStyle='#14272bdc';g.fillRect(0,0,480,300);g.fillStyle='#d8f075';g.font='bold 28px monospace';g.fillText(r.paused?'PAUSED':`READY ${Math.ceil(r.ready)}`,240,145);g.font='12px monospace';g.fillText(r.paused?'Press Resume to continue':'Gold = collect. Pink = dodge.',240,178)}$('#run-count').textContent=`◆ ${r.caught} / 8`;$('#run-life').textContent='♥ '.repeat(r.hearts)+'♡ '.repeat(3-r.hearts);$('#run-time').textContent=`${Math.ceil(Math.max(0,r.time))}s`;}
function frame(t){const dt=Math.min((t-lastFrame)/1000||0,.04);lastFrame=t;if(run)updateRun(dt);else if(state.started&&!dialog.open){let dx=(held.has('d')||held.has('arrowright')?1:0)-(held.has('a')||held.has('arrowleft')?1:0),dy=(held.has('s')||held.has('arrowdown')?1:0)-(held.has('w')||held.has('arrowup')?1:0);if(destination&&!dx&&!dy){dx=destination.x-state.player.x;dy=destination.y-state.player.y;if(Math.hypot(dx,dy)<5){destination=null;dx=dy=0}}const length=Math.hypot(dx,dy);if(length){dx/=length;dy/=length;lastDirection={x:dx,y:dy};const speed=held.has('shift')||t<dashUntil?300:160;const oldX=state.player.x,oldY=state.player.y;walk(dx*speed*dt,dy*speed*dt);if(destination&&oldX===state.player.x&&oldY===state.player.y)destination=null}particles=particles.map(p=>({...p,t:p.t-dt})).filter(p=>p.t>0);draw()}requestAnimationFrame(frame)}
render();requestAnimationFrame(frame);
